-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — VYSOČINA 2026 (10 tras, sort 2100+)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Zámky na Oslavě – Velké Meziříčí a Náměšť
  delete from public.routes where name = 'Zámky na Oslavě – Velké Meziříčí a Náměšť' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Zámky na Oslavě – Velké Meziříčí a Náměšť', 'Pohodový zámecký okruh sleduje údolí řeky Oslavy a spojuje dvě velkolepá šlechtická sídla — renesanční Velké Meziříčí pod obřím dálničním mostem a majestátní Náměšť nad Oslavou na kopci nad barokním mostem se sochami. Jede se po klidných silnicích II. a III. třídy zvlněnou krajinou mezi rybníky, lesy a poli, s příjemně svižnými pasážemi mezi Budišovem a Náměští. Cestou zpět si užijete táhlé zatáčky podél Třebíčska přes Vladislav. Trasa je vhodná i pro méně zkušené jezdce a nejlépe chutná od jara do podzimu. Pozor na zemědělskou techniku na okreskách a na dlážděné úseky v centrech měst.', 'loop', 195, 255, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.3556, "lng": 16.0135, "label": "Velké Meziříčí – zámek"}, {"lat": 49.2716, "lng": 16.0010, "label": "Zámek Budišov"}, {"lat": 49.2075, "lng": 16.1594, "label": "Zámek Náměšť nad Oslavou"}, {"lat": 49.2103, "lng": 15.9895, "label": "Vladislav"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.3556,16.0135%7C49.2716,16.0010%7C49.2075,16.1594%7C49.2103,15.9895', 'https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou_castle_in_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_T%C5%99eb%C3%AD%C4%8D_District.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9_Mezi%C5%99%C3%AD%C4%8D%C3%AD%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%A1lni%C4%8Dn%C3%AD_most_Vyso%C4%8Dina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9_Mezi%C5%99%C3%AD%C4%8D%C3%AD%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Budi%C5%A1ov%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou_castle_in_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_T%C5%99eb%C3%AD%C4%8D_District.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_kamenn%C3%BD_most.jpg"}'::text[], '{"Zámek Velké Meziříčí","Dálniční most Vysočina","Restaurace: Jelínkova vila (Velké Meziříčí)","Zámek Budišov","Zámek Náměšť nad Oslavou","Barokní kamenný most v Náměšti nad Oslavou"}'::text[], '{"CZ"}'::text[], false, 2110, 'approved');

  -- Polná, Brtnice a zřícenina Rokštejn
  delete from public.routes where name = 'Polná, Brtnice a zřícenina Rokštejn' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Polná, Brtnice a zřícenina Rokštejn', 'Kratší okruh kolem Jihlavy propojuje tři méně známé perly Vysočiny — hradozámecký areál v Polné s jednou z nejcennějších synagog v Česku, romantickou zříceninu Rokštejn v údolí řeky Brtnice a renesanční městečko Brtnici, rodiště architekta Josefa Hoffmanna. Silnice třetí třídy se vinou mezi rybníky, remízky a lesíky typické vrchovinné krajiny a nabízejí pohodovou, nenáročnou jízdu. Závěr patří zámku v Třešti a návratu přes lesnaté hřebeny. Ideální půldenní vyjížďka pro každého, nejhezčí od května do října. Pozor na úzkou asfaltku k Rokštejnu a na dlažbu na náměstích.', 'loop', 135, 190, 'easy',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.4879, "lng": 15.7166, "label": "Polná"}, {"lat": 49.3399, "lng": 15.7124, "label": "Zřícenina Rokštejn"}, {"lat": 49.3070, "lng": 15.6763, "label": "Brtnice"}, {"lat": 49.2938, "lng": 15.4803, "label": "Třešť"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.4879,15.7166%7C49.3399,15.7124%7C49.3070,15.6763%7C49.2938,15.4803', 'https://commons.wikimedia.org/wiki/Special:FilePath/Poln%C3%A1%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poln%C3%A1%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Poln%C3%A1%2C_synagoga.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Rok%C5%A1tejn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Brtnice%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99e%C5%A1%C5%A5%2C_z%C3%A1mek.jpg"}'::text[], '{"Hrad a zámek Polná","Synagoga a rabínský dům v Polné","Zřícenina hradu Rokštejn","Zámek Brtnice","Zámek Třešť"}'::text[], '{"CZ"}'::text[], false, 2120, 'approved');

  -- Údolím Želetavky – Police, Jemnice a Uherčice
  delete from public.routes where name = 'Údolím Želetavky – Police, Jemnice a Uherčice' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolím Želetavky – Police, Jemnice a Uherčice', 'Objevitelský okruh nejjižnějším cípem Vysočiny míří do kraje, kam běžný turista skoro nezabloudí — do údolí říčky Želetavky mezi Jemnicí a moravsko-rakouským pomezím. Čekají vás prázdné okresky se svižnými zatáčkami, hrad Sádek nad vinicí, zámek v Polici s leteckým muzeem i monumentální, zvolna ožívající zámek Uherčice. Historická Jemnice s hradbami je ideální na kávu v polovině cesty. Trasa je středně náročná délkou, nikoli technikou, a nejlépe si ji užijete od jara do podzimu. Pozor na zvěř v lesních úsecích a místy hrubší asfalt na třetitřídkách.', 'loop', 195, 260, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.1866, "lng": 15.8366, "label": "Hrad Sádek"}, {"lat": 49.0522, "lng": 15.8093, "label": "Moravské Budějovice"}, {"lat": 48.9690, "lng": 15.7091, "label": "Zámek Police"}, {"lat": 48.9153, "lng": 15.6413, "label": "Zámek Uherčice"}, {"lat": 49.0190, "lng": 15.5699, "label": "Jemnice"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.1866,15.8366%7C49.0522,15.8093%7C48.9690,15.7091%7C48.9153,15.6413%7C49.0190,15.5699', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_S%C3%A1dek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_S%C3%A1dek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Moravsk%C3%A9_Bud%C4%9Bjovice%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Police%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Uher%C4%8Dice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jemnice%2C_n%C3%A1m%C4%9Bst%C3%AD_Svobody.jpg"}'::text[], '{"Hrad Sádek","Zámek Moravské Budějovice","Zámek Police a letecké muzeum","Zámek Uherčice","Jemnice – historické město nad Želetavkou"}'::text[], '{"CZ"}'::text[], false, 2130, 'approved');

  -- Dalešice a Mohelno – přehrady v údolí Jihlavy
  delete from public.routes where name = 'Dalešice a Mohelno – přehrady v údolí Jihlavy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dalešice a Mohelno – přehrady v údolí Jihlavy', 'Okruh kolem dvojice přehrad v hlubokém kaňonu řeky Jihlavy kombinuje velkou vodu, technické zajímavosti a slavný filmový pivovar. Z Třebíčska se spustíte k obloukovému Stropešínskému mostu, po hrázi nejvyšší sypané přehrady v Česku přejedete nad stometrovou hloubkou a od vyrovnávací nádrže Mohelno dohlédnete až k chladicím věžím Dukovan. Cestou zpět čeká zasloužená zastávka v pivovaru Dalešice, kde se točily Postřižiny. Silnice kolem přehrad jsou samá zatáčka a v sezóně láká i koupání. Pozor na cyklisty na hrázích a o víkendech na hustší provoz u pivovaru.', 'loop', 205, 270, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.2160, "lng": 15.8820, "label": "Třebíč – průjezd"}, {"lat": 49.1450, "lng": 16.0760, "label": "Stropešínský most"}, {"lat": 49.1320, "lng": 16.1200, "label": "Hráz Dalešické přehrady"}, {"lat": 49.1093, "lng": 16.1743, "label": "Vodní nádrž Mohelno"}, {"lat": 49.0866, "lng": 16.1465, "label": "Infocentrum JE Dukovany"}, {"lat": 49.1290, "lng": 16.0820, "label": "Pivovar Dalešice"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.2160,15.8820%7C49.1450,16.0760%7C49.1320,16.1200%7C49.1093,16.1743%7C49.0866,16.1465%7C49.1290,16.0820', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C5%A1ick%C3%A1_p%C5%99ehrada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strope%C5%A1%C3%ADnsk%C3%BD_most.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C5%A1ick%C3%A1_p%C5%99ehrada.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD_n%C3%A1dr%C5%BE_Mohelno.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dukovany_Nuclear_Power_Station.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C5%A1ice%2C_pivovar.jpg"}'::text[], '{"Stropešínský most","Dalešická přehrada – hráz Kramolín","Vodní nádrž Mohelno","Infocentrum JE Dukovany","Restaurace: Pivovar Dalešice (Dalešice)"}'::text[], '{"CZ"}'::text[], false, 2140, 'approved');

  -- Vírská přehrada a horní Svratka
  delete from public.routes where name = 'Vírská přehrada a horní Svratka' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Vírská přehrada a horní Svratka', 'Celodenní výprava do nejhornatějšího kouta Vysočiny sleduje divoké údolí horní Svratky, kterému vévodí štíhlá betonová hráz Vírské přehrady. Kolem vodní nádrže se na skalních ostrozích krčí hned tři romantické zříceniny — Aueršperk, Pyšolec a hrad v Dalečíně přímo u řeky. Silnice se tu kroutí serpentinami po stráních, střídají hluboké lesy a výhledy na hladinu, závěr patří malebnému Jimramovu, rodišti bratří Mrštíků. Nejkrásnější je trasa na přelomu září a října, kdy údolí hraje barvami. Pozor na vlhký asfalt ve stinných úsecích a úzké silničky kolem přehrady.', 'loop', 220, 290, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.5545, "lng": 16.2960, "label": "Zřícenina Aueršperk"}, {"lat": 49.5486, "lng": 16.3115, "label": "Zřícenina Pyšolec"}, {"lat": 49.5697, "lng": 16.3226, "label": "Vírská přehrada"}, {"lat": 49.5901, "lng": 16.2542, "label": "Dalečín"}, {"lat": 49.6366, "lng": 16.2258, "label": "Jimramov"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.5545,16.2960%7C49.5486,16.3115%7C49.5697,16.3226%7C49.5901,16.2542%7C49.6366,16.2258', 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADrsk%C3%A1_p%C5%99ehrada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Auer%C5%A1perk.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Py%C5%A1olec.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADrsk%C3%A1_p%C5%99ehrada.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C4%8D%C3%ADn%2C_hrad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jimramov%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg"}'::text[], '{"Zřícenina hradu Aueršperk","Zřícenina hradu Pyšolec","Vírská přehrada","Zřícenina hradu Dalečín","Jimramov"}'::text[], '{"CZ"}'::text[], false, 2150, 'approved');

  -- Rozhledny Havlíčkobrodska
  delete from public.routes where name = 'Rozhledny Havlíčkobrodska' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rozhledny Havlíčkobrodska', 'Vyhlídkový okruh severní Vysočinou spojuje tři rozhledny, ze kterých přehlédnete kraj mezi Sázavou a Doubravou jako na dlani — dřevěnou Bohdanku, ocelovou Vysokou u Havlíčkova Brodu a kamennou Rosičku u Sázavy. Mezi věžemi se jede po zvlněných okreskách s dlouhými výhledy, stoupáními a sjezdy typickými pro Havlíčkobrodsko. Cestou přibude zámek v Přibyslavi a tichá mohyla připomínající místo, kde zemřel Jan Žižka. Trasa je nenáročná na techniku, ale dlouhá na kilometry — počítejte s celým dnem včetně výstupů na věže. Nejlepší viditelnost bývá na jaře a na podzim, pozor na větrné hřebeny.', 'loop', 195, 260, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.7770, "lng": 15.2170, "label": "Rozhledna Bohdanka"}, {"lat": 49.5770, "lng": 15.5230, "label": "Rozhledna Vysoká"}, {"lat": 49.5769, "lng": 15.7387, "label": "Přibyslav"}, {"lat": 49.5992, "lng": 15.7169, "label": "Žižkova mohyla"}, {"lat": 49.5288, "lng": 15.8570, "label": "Rozhledna Rosička"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.7770,15.2170%7C49.5770,15.5230%7C49.5769,15.7387%7C49.5992,15.7169%7C49.5288,15.8570', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Bohdanka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Bohdanka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Vysok%C3%A1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99ibyslav%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C5%BEkova_mohyla.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Rosi%C4%8Dka.jpg"}'::text[], '{"Rozhledna Bohdanka","Rozhledna Vysoká","Zámek Přibyslav","Žižkova mohyla","Rozhledna Rosička"}'::text[], '{"CZ"}'::text[], false, 2160, 'approved');

  -- Rozhledny Třebíčska – Mařenka a Babylon
  delete from public.routes where name = 'Rozhledny Třebíčska – Mařenka a Babylon' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Rozhledny Třebíčska – Mařenka a Babylon', 'Vyhlídkový okruh jižní Vysočinou spojuje nejvyšší bod Třebíčska s nejstarší rozhlednou na Moravě. Z rozhledny Mařenka u Štěměch přehlédnete půl kraje, u Třebíče vystoupáte na Pekelný kopec s moderní věží inspirovanou židovskou hvězdou a závěr obstará klasicistní Babylon u Kramolína, odkud se rozhlíželi zeměměřiči už v 19. století. Mezi věžemi se jede po prázdných okreskách se svižným rytmem zatáček, cestou přibude větrný mlýn v Třebíči a zámek ve Valči. Trasa je středně dlouhá a technicky nenáročná, nejlépe si ji vychutnáte za jasného dne s dobrou viditelností. Pozor na lesní úseky s možným štěrkem u krajnic.', 'loop', 190, 250, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.1919, "lng": 15.7391, "label": "Rozhledna Mařenka"}, {"lat": 49.2202, "lng": 15.8688, "label": "Třebíč – větrný mlýn"}, {"lat": 49.1950, "lng": 15.8700, "label": "Pekelný kopec"}, {"lat": 49.1707, "lng": 16.0316, "label": "Zámek Valeč"}, {"lat": 49.1112, "lng": 16.1700, "label": "Rozhledna Babylon"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.1919,15.7391%7C49.2202,15.8688%7C49.1950,15.8700%7C49.1707,16.0316%7C49.1112,16.1700', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Ma%C5%99enka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Ma%C5%99enka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D%2C_v%C4%9Btrn%C3%BD_ml%C3%BDn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Pekeln%C3%BD_kopec.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vale%C4%8D%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Babylon.jpg"}'::text[], '{"Rozhledna Mařenka","Větrný mlýn v Třebíči","Rozhledna Pekelný kopec","Zámek Valeč","Rozhledna Babylon"}'::text[], '{"CZ"}'::text[], false, 2170, 'approved');

  -- Mohelenská hadcová step a údolí Oslavy
  delete from public.routes where name = 'Mohelenská hadcová step a údolí Oslavy' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Mohelenská hadcová step a údolí Oslavy', 'Přírodní okruh na jihovýchodě Vysočiny vede krajinou hlubokých říčních kaňonů, které tu vyhlodaly Oslava s Jihlavou. Vrcholem je Mohelenská hadcová step — národní rezervace nad obří smyčkou řeky, kde na hadcovém podloží přežívá stepní fauna a flóra jako nikde jinde ve střední Evropě. Cestou navštívíte památník Bible kralické, divoké údolí Oslavy a Chvojnice se zříceninou Levnov i tajemný templářský Templštejn nad Jihlavou. Mezi zastávkami si užijete prázdné okresky se svižnými zatáčkami a minimem provozu. Ke zříceninám se chodí kus pěšky po lesních stezkách, počítejte s pevnou obuví; nejkrásněji je tu na jaře a začátkem léta.', 'loop', 215, 285, 'medium',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.1985, "lng": 16.2015, "label": "Kralice nad Oslavou"}, {"lat": 49.1650, "lng": 16.2350, "label": "Údolí Oslavy a Chvojnice"}, {"lat": 49.1585, "lng": 16.2646, "label": "Zřícenina Levnov"}, {"lat": 49.0946, "lng": 16.2477, "label": "Zřícenina Templštejn"}, {"lat": 49.1067, "lng": 16.1878, "label": "Mohelenská hadcová step"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.1985,16.2015%7C49.1650,16.2350%7C49.1585,16.2646%7C49.0946,16.2477%7C49.1067,16.1878', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mohelensk%C3%A1_hadcov%C3%A1_step.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kralice_nad_Oslavou%2C_pam%C3%A1tn%C3%ADk_Bible_kralick%C3%A9.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Adol%C3%AD_Oslavy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Levnov.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Templ%C5%A1tejn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mohelensk%C3%A1_hadcov%C3%A1_step.jpg"}'::text[], '{"Památník Bible kralické","Údolí Oslavy a Chvojnice","Zřícenina Levnov (Ketkovický hrad)","Zřícenina Templštejn","Mohelenská hadcová step"}'::text[], '{"CZ"}'::text[], false, 2180, 'approved');

  -- Údolí Doubravy a Stvořidla
  delete from public.routes where name = 'Údolí Doubravy a Stvořidla' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí Doubravy a Stvořidla', 'Přírodní okruh severní Vysočinou spojuje dva nejdivočejší říční úseky kraje — skalnatý kaňon Doubravy u Chotěboře a peřeje Stvořidla na Sázavě, kde řeka duní mezi balvany jako na horách. Mezi nimi se jede po klidných okreskách zvlněnou krajinou polí a lesů, s příjemnou zastávkou u zámku v Chotěboři a u prastarého tisu ve Vilémovicích, kterému botanici hádají až dva tisíce let. Závěrečná smyčka obchází horu Melechov, bájný střed Evropy. K oběma údolím se od silnice chodí kus pěšky, hezčí zážitek si odnesete v pevných botách. Trasa je krátká a pohodová, ideální na půlden s dlouhými zastávkami v přírodě.', 'loop', 155, 210, 'easy',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.6880, "lng": 15.6950, "label": "Bílek – Údolí Doubravy"}, {"lat": 49.7200, "lng": 15.6740, "label": "Chotěboř"}, {"lat": 49.7107, "lng": 15.3454, "label": "Vilémovice"}, {"lat": 49.6650, "lng": 15.3500, "label": "Stvořidla"}, {"lat": 49.6486, "lng": 15.3103, "label": "Melechov"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.6880,15.6950%7C49.7200,15.6740%7C49.7107,15.3454%7C49.6650,15.3500%7C49.6486,15.3103', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Adol%C3%AD_Doubravy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Adol%C3%AD_Doubravy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chot%C4%9Bbo%C5%99%2C_z%C3%A1mek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chot%C4%9Bbo%C5%99%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vil%C3%A9movick%C3%BD_tis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stvo%C5%99idla.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Melechov.jpg"}'::text[], '{"Údolí Doubravy","Zámek Chotěboř","Restaurace: Panský dům (Chotěboř)","Vilémovický tis","Stvořidla","Melechov"}'::text[], '{"CZ"}'::text[], false, 2190, 'approved');

  -- Za muzei a podzemím Jihlavska
  delete from public.routes where name = 'Za muzei a podzemím Jihlavska' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Za muzei a podzemím Jihlavska', 'Muzejní okruh středem Vysočiny je ideální volbou pro dny, kdy chcete střídat jízdu s poznáváním. Začíná v hornické Jihlavě, kde sestoupíte do druhého největšího podzemního labyrintu v Česku, projdete expozice Muzea Vysočiny na náměstí a vyfotíte si hradební bránu Matky Boží. Pak trasa uhne na sever k technické památce Šlakhamr, vodnímu hamru u Sázavy, a přes Havlíčkův Brod s rodným domem Karla Havlíčka Borovského dorazí na středověký selský statek v Pohledi. Jede se po pohodových silnicích druhé a třetí třídy bez technických záludností. Počítejte s celým dnem — samotné prohlídky zaberou víc času než jízda; v pondělí bývá většina expozic zavřená.', 'loop', 160, 215, 'easy',
     '[{"lat": 49.3464, "lng": 15.2119, "label": "Start: Mezná u Pelhřimova"}, {"lat": 49.3956, "lng": 15.5907, "label": "Jihlava"}, {"lat": 49.5570, "lng": 15.8890, "label": "Šlakhamr"}, {"lat": 49.6079, "lng": 15.5806, "label": "Havlíčkův Brod"}, {"lat": 49.6550, "lng": 15.4570, "label": "Pohleď"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl: Mezná u Pelhřimova"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.3956,15.5907%7C49.5570,15.8890%7C49.6079,15.5806%7C49.6550,15.4570', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_br%C3%A1na_Matky_Bo%C5%BE%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jihlavsk%C3%A9_podzem%C3%AD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_Masarykovo_n%C3%A1m%C4%9Bst%C3%AD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_br%C3%A1na_Matky_Bo%C5%BE%C3%AD.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_radnice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0lakhamr.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Havl%C3%AD%C4%8Dk%C5%AFv_Brod%2C_Havl%C3%AD%C4%8Dk%C5%AFv_d%C5%AFm.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pohle%C4%8F%2C_Michal%C5%AFv_statek.jpg"}'::text[], '{"Jihlavské podzemí","Muzeum Vysočiny Jihlava","Brána Matky Boží","Restaurace: Radniční restaurace (Jihlava)","Šlakhamr","Havlíčkův dům (Havlíčkův Brod)","Michalův statek v Pohledi"}'::text[], '{"CZ"}'::text[], false, 2200, 'approved');

end $$;
