  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Velké Meziříčí', 'Renesanční zámek rodu Podstatzky-Lichtenstein se tyčí na skále přímo nad centrem města, v místě, kde se stéká Oslava s Balinkou. Prohlídkové okruhy vedou zařízenými salony a muzeem, z terasy je pěkný pohled na město sevřené v hlubokém údolí. Motorku pohodlně zaparkujete pod zámkem a centrum projdete pěšky.', 49.3556, 16.0135, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9_Mezi%C5%99%C3%AD%C4%8D%C3%AD%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9_Mezi%C5%99%C3%AD%C4%8D%C3%AD%2C_z%C3%A1mek.jpg"}'::text[], 0),
    (v_route, 'Dálniční most Vysočina', 'Ikonický ocelový most dálnice D1 překlenuje údolí Oslavy ve výšce přes 75 metrů přímo nad městem a patří k největším mostům v Česku. Pohled zespodu od řeky na obří konstrukci nad střechami Velkého Meziříčí je nezapomenutelný. Skvělé místo na rychlou fotozastávku hned na začátku okruhu.', 49.3520, 16.0037, 'https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%A1lni%C4%8Dn%C3%AD_most_Vyso%C4%8Dina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%A1lni%C4%8Dn%C3%AD_most_Vyso%C4%8Dina.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Jelínkova vila (Velké Meziříčí)', 'Stylová restaurace v prvorepublikové vile u řeky Oslavy s vlastním rodinným pivovarem Harrach. Nabízí poctivou českou i moderní kuchyni a čerstvě uvařené nefiltrované pivo, hosté ji dlouhodobě řadí k nejlépe hodnoceným podnikům ve městě. Ideální zastávka na oběd hned v první třetině okruhu.', 49.3546, 16.0089, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9_Mezi%C5%99%C3%AD%C4%8D%C3%AD%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velk%C3%A9_Mezi%C5%99%C3%AD%C4%8D%C3%AD%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg"}'::text[], 2),
    (v_route, 'Zámek Budišov', 'Barokně upravený zámek obklopený anglickým parkem s rybníkem ukrývá unikátní zoologický depozitář Moravského zemského muzea — tisíce vycpanin zvířat z celého světa v historických sálech. Prohlídka je nečekaný zážitek, jaký jinde na Vysočině nenajdete. Klidná zastávka uprostřed tiché vesnické krajiny mezi Meziříčím a Náměští.', 49.2716, 16.0010, 'https://commons.wikimedia.org/wiki/Special:FilePath/Budi%C5%A1ov%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Budi%C5%A1ov%2C_z%C3%A1mek.jpg"}'::text[], 3),
    (v_route, 'Zámek Náměšť nad Oslavou', 'Renesanční zámek Žerotínů na zalesněném kopci nad městem býval letním sídlem prezidenta Beneše a dnes je národní kulturní památkou. Prohlídky nabízejí vzácnou sbírku tapiserií, knihovnu a kapli, z nádvoří se otevírá výhled do údolí Oslavy. Příjezdová alej a serpentina pod zámkem je hezkou tečkou pro motorkáře.', 49.2075, 16.1594, 'https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou_castle_in_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_T%C5%99eb%C3%AD%C4%8D_District.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou_castle_in_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_T%C5%99eb%C3%AD%C4%8D_District.jpg"}'::text[], 4),
    (v_route, 'Barokní kamenný most v Náměšti nad Oslavou', 'Kamenný most přes Oslavu z roku 1737 zdobí dvacet barokních soch světců — po pražském Karlově mostě jde o nejcennější sochařsky zdobený most v Česku. Stojí přímo pod zámkem v centru města a je ideálním místem na závěrečnou fotku před zpáteční cestou. Přes most se dnes jezdí jen jedním směrem, choďte raději pěšky.', 49.2060, 16.1585, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_kamenn%C3%BD_most.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_kamenn%C3%BD_most.jpg"}'::text[], 5);
  insert into public.routes
