  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad a zámek Polná', 'Rozlehlý hradozámecký areál nad Peklem, jak se říká údolí pod hradbami, dnes hostí muzeum s expozicí lékárny, školní třídy a měšťanského bydlení. Gotický hrad přestavěný na zámek dominuje malebnému městečku s obřím Husovým náměstím. Příjemná první zastávka s parkováním přímo u brány areálu.', 49.4879, 15.7166, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poln%C3%A1%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poln%C3%A1%2C_z%C3%A1mek.jpg"}'::text[], 0),
    (v_route, 'Synagoga a rabínský dům v Polné', 'Barokní synagoga z roku 1684 s rabínským domem patří k nejcennějším židovským památkám v Česku a připomíná i neblaze proslulou hilsneriádu. Expozice Regionálního muzea vypráví o životě židovské komunity na malém městě. Stojí v dochovaném ghettu pár kroků od náměstí, prohlídka zabere půl hodinky.', 49.4869, 15.7146, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poln%C3%A1%2C_synagoga.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poln%C3%A1%2C_synagoga.jpg"}'::text[], 1),
    (v_route, 'Zřícenina hradu Rokštejn', 'Rozeklaná zřícenina gotického hradu ze 13. století se zvedá na skále přímo nad meandrem říčky Brtnice u Přímělkova. Patří k nejstarším hradům na Moravě a díky dochované hranolové věži je vděčným cílem fotografů. Od silnice je to k hradu jen krátká procházka údolím.', 49.3399, 15.7124, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Rok%C5%A1tejn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Rok%C5%A1tejn.jpg"}'::text[], 2),
    (v_route, 'Zámek Brtnice', 'Renesanční zámek Collaltů shlíží na městečko s malebným náměstím, barokními mosty se sochami a rodným domem světoznámého architekta Josefa Hoffmanna. Průjezd Brtnicí údolím stejnojmenné říčky patří k nejhezčím pasážím okruhu. Zámek je postupně opravován, kouzlo místa ale funguje i zvenčí.', 49.3070, 15.6763, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brtnice%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brtnice%2C_z%C3%A1mek.jpg"}'::text[], 3),
    (v_route, 'Zámek Třešť', 'Klasicistně upravený zámek s anglickým parkem v městečku proslulém výrobou betlémů — místní betlémářská tradice trvá přes dvě stě let. Dnes zámek slouží jako hotel a konferenční centrum Akademie věd, park je volně přístupný. Poslední zastávka před návratem přes lesy Javořické vrchoviny.', 49.2938, 15.4803, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99e%C5%A1%C5%A5%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99e%C5%A1%C5%A5%2C_z%C3%A1mek.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Sádek', 'Hrad přestavěný na zámek stojí na výrazném kopci u Kojetic a pod jeho zdmi se rozkládá nejstarší moravská vinice mimo tradiční vinařské oblasti. Místní vinařství nabízí degustace a z vrchu je krásný rozhled po Třebíčsku. Nezvyklé spojení hradu a vína je skvělým zahájením okruhu.', 49.1866, 15.8366, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_S%C3%A1dek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_S%C3%A1dek.jpg"}'::text[], 0),
    (v_route, 'Zámek Moravské Budějovice', 'Renesanční zámek na náměstí v Moravských Budějovicích ukrývá muzeum s unikátní expozicí starých řemesel — uvidíte dílny bednáře, koláře, provazníka i perníkáře v původním vybavení. Město je přirozenou branou do kraje mezi Vysočinou a Podyjím. Parkování přímo na náměstí, zastávka na kávu se nabízí.', 49.0522, 15.8093, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moravsk%C3%A9_Bud%C4%9Bjovice%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moravsk%C3%A9_Bud%C4%9Bjovice%2C_z%C3%A1mek.jpg"}'::text[], 1),
    (v_route, 'Zámek Police a letecké muzeum', 'Renesanční zámek v malé vsi nad údolím Želetavky překvapí nečekaným obsahem — sídlí tu letecké muzeum s desítkami strojů včetně stíhaček MiG a vrtulníků, věnované osudům letců z regionu. Kombinace starých zdí a proudových letadel je zážitek, který jinde nezažijete. Otevírací dobu si raději ověřte předem.', 48.9690, 15.7091, 'https://commons.wikimedia.org/wiki/Special:FilePath/Police%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Police%2C_z%C3%A1mek.jpg"}'::text[], 2),
    (v_route, 'Zámek Uherčice', 'Obrovský renesančně-barokní komplex na samé hranici s Rakouskem patřil k nejzanedbanějším památkám země a dnes se po rozsáhlé obnově vrací do života. Prohlídka syrových i obnovených sálů ukazuje, jak se zámek zachraňuje, okolní anglický park zve k procházce. Silnice sem vedou liduprázdnou krajinou bývalé železné opony.', 48.9153, 15.6413, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Uher%C4%8Dice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Uher%C4%8Dice.jpg"}'::text[], 3),
    (v_route, 'Jemnice – historické město nad Želetavkou', 'Jedno z nejstarších moravských měst se pyšní zachovalými hradbami, židovskou čtvrtí a tradicí slavnosti Barchan, která se koná už přes šest set let. Náměstí Svobody s podloubím je příjemné místo na oběd či kávu v druhé polovině okruhu. Z hradebního okruhu jsou hezké výhledy do údolí Želetavky.', 49.0190, 15.5699, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jemnice%2C_n%C3%A1m%C4%9Bst%C3%AD_Svobody.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jemnice%2C_n%C3%A1m%C4%9Bst%C3%AD_Svobody.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Stropešínský most', 'Elegantní obloukový most překlenuje boční rameno Dalešické přehrady u Stropešína a patří k nejfotogeničtějším stavbám na celé nádrži. Z mostu i z břehů se otevírají výhledy na klikatící se hladinu sevřenou lesnatými stráněmi. Ideální první fotozastávka u velké vody.', 49.1450, 16.0760, 'https://commons.wikimedia.org/wiki/Special:FilePath/Strope%C5%A1%C3%ADnsk%C3%BD_most.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strope%C5%A1%C3%ADnsk%C3%BD_most.jpg"}'::text[], 0),
    (v_route, 'Dalešická přehrada – hráz Kramolín', 'Sypaná hráz vysoká sto metrů je nejvyšší svého druhu v Česku a zadržuje dvaadvacet kilometrů dlouhé jezero v kaňonu Jihlavy. Přehrada slouží přečerpávací elektrárně spolupracující s Dukovany a z koruny hráze je závratný pohled do hloubky údolí. U hráze funguje vyhlídka i občerstvení, v létě jezdí po jezeře výletní loď.', 49.1320, 16.1200, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C5%A1ick%C3%A1_p%C5%99ehrada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C5%A1ick%C3%A1_p%C5%99ehrada.jpg"}'::text[], 1),
    (v_route, 'Vodní nádrž Mohelno', 'Vyrovnávací nádrž pod dalešickou hrází se vine hlubokým skalnatým kaňonem a její tyrkysová hladina kontrastuje s divokými stráněmi nad ní. Z vyhlídek na okraji Mohelna je jeden z nejdramatičtějších pohledů na říční krajinu Vysočiny. Krátká odbočka, která rozhodně stojí za to.', 49.1093, 16.1743, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD_n%C3%A1dr%C5%BE_Mohelno.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD_n%C3%A1dr%C5%BE_Mohelno.jpg"}'::text[], 2),
    (v_route, 'Infocentrum JE Dukovany', 'Bezplatné návštěvnické centrum největší tuzemské jaderné elektrárny vysvětluje na modelech a simulátorech, jak se z atomu vyrábí elektřina. Pohled na čtveřici chladicích věží zblízka je působivý a expozice zabere příjemnou hodinku. Motorkáři tu najdou stín, občerstvení a téma k hovoru na zbytek cesty.', 49.0866, 16.1465, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dukovany_Nuclear_Power_Station.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dukovany_Nuclear_Power_Station.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Pivovar Dalešice (Dalešice)', 'Legendární pivovar, kde Jiří Menzel natáčel Postřižiny, dnes vaří nefiltrovaná piva a v pivovarské hospodě servíruje poctivou českou kuchyni. Hosté chválí tankové pivo, vepřové speciality i atmosféru starých spilek, hodnocení se dlouhodobě drží vysoko. Perfektní pozdní oběd před zpáteční cestou — řidič samozřejmě jen nealko.', 49.1290, 16.0820, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C5%A1ice%2C_pivovar.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C5%A1ice%2C_pivovar.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zřícenina hradu Aueršperk', 'Tajemné zbytky hradu ze 13. století se skrývají v lesích nad údolím Bystřice nedaleko Dvořišť. Dochovaly se mohutné valy a torza zdí, které obrostl mech — místo má syrovou atmosféru dávno zaniklé pevnosti. Od silnice sem vede krátká lesní procházka, ideální na protažení nohou.', 49.5545, 16.2960, 'https://commons.wikimedia.org/wiki/Special:FilePath/Auer%C5%A1perk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Auer%C5%A1perk.jpg"}'::text[], 0),
    (v_route, 'Zřícenina hradu Pyšolec', 'Zřícenina na strmém ostrohu vysoko nad zákrutem Svratky, z jejíhož okruží zbylo torzo válcového bergfritu a hradby. Výstup od řeky je strmější, odměnou jsou ale výhledy do zalesněného údolí pod Vírskou přehradou. Jeden z nejromantičtějších hradů Vysočiny, o kterém většina lidí nikdy neslyšela.', 49.5486, 16.3115, 'https://commons.wikimedia.org/wiki/Special:FilePath/Py%C5%A1olec.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Py%C5%A1olec.jpg"}'::text[], 1),
    (v_route, 'Vírská přehrada', 'Betonová tížná hráz z padesátých let se zvedá do výšky přes sedmdesát metrů a zadržuje pitnou vodu pro Brněnsko v deset kilometrů dlouhém jezeře. Pohled z vyhlídky na štíhlou korunu hráze sevřenou lesnatými srázy patří k nejpůsobivějším na Moravě. Kolem přehrady vede krásná vyhlídková silnice do obce Vír.', 49.5697, 16.3226, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADrsk%C3%A1_p%C5%99ehrada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADrsk%C3%A1_p%C5%99ehrada.jpg"}'::text[], 2),
    (v_route, 'Zřícenina hradu Dalečín', 'Neobvyklá zřícenina stojí přímo v obci na břehu Svratky — z hradu se dochovala výrazná okrouhlá stěna paláce, která se zrcadlí v řece. Podle pověsti hrad dobýval i Jan Žižka. Zastávka je pohodlná, hrad je pár metrů od silnice u mostu.', 49.5901, 16.2542, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C4%8D%C3%ADn%2C_hrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dale%C4%8D%C3%ADn%2C_hrad.jpg"}'::text[], 3),
    (v_route, 'Jimramov', 'Malebný městys na soutoku Svratky a Fryšávky je rodištěm bratří Mrštíků i Jana Karafiáta, autora Broučků. Náměstíčko s barokními domy a zámkem působí, jako by se tu zastavil čas. Příjemné místo na kávu a poslední fotky před zpáteční cestou přes hřebeny Žďárských vrchů.', 49.6366, 16.2258, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jimramov%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jimramov%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rozhledna Bohdanka', 'Dřevěná rozhledna nad obcí Bohdaneč nabízí z ochozu kruhový výhled na Železné hory, údolí Sázavy a za dobré viditelnosti až na Krkonoše. Věž stojí uprostřed lesů stranou hlavních tahů, takže tu často budete úplně sami. Od parkoviště je to na vrchol jen pár minut chůze.', 49.7770, 15.2170, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Bohdanka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Bohdanka.jpg"}'::text[], 0),
    (v_route, 'Rozhledna Vysoká', 'Štíhlá věž na stejnojmenném kopci jihozápadně od Havlíčkova Brodu vyrostla nad lesy v nadmořské výšce přes 600 metrů. Z ochozu dohlédnete na Žďárské vrchy, Železné hory i hluboké lesy nad Sázavou. Krátká odbočka z okresky, která spolehlivě provětrá nohy po sedle.', 49.5770, 15.5230, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Vysok%C3%A1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Vysok%C3%A1.jpg"}'::text[], 1),
    (v_route, 'Zámek Přibyslav', 'Renesanční zámek nad údolím Sázavy hostí kuriózní Centrum hasičského hnutí — největší hasičské muzeum v zemi s historickými stříkačkami a technikou. Městečko s podloubím na náměstí je příjemnou zastávkou na kávu. Kolem zámku vede hezká vyhlídková cesta nad řekou.', 49.5769, 15.7387, 'https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99ibyslav%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99ibyslav%2C_z%C3%A1mek.jpg"}'::text[], 2),
    (v_route, 'Žižkova mohyla', 'Kamenná mohyla u Žižkova Pole označuje místo, kde podle tradice 11. října 1424 zemřel při obléhání Přibyslavi Jan Žižka z Trocnova. Památník z 19. století stojí uprostřed polí s dalekým výhledem a působí tichou, skoro poutní atmosférou. Zastávka na pět minut, na kterou budete vzpomínat.', 49.5992, 15.7169, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C5%BEkova_mohyla.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C5%BEkova_mohyla.jpg"}'::text[], 3),
    (v_route, 'Rozhledna Rosička', 'Kamenno-dřevěná rozhledna na vrchu Rosička u Sázavy stojí v nejvyšším bodě širokého okolí a nabízí jeden z nejhezčích kruhových výhledů na Žďárské vrchy. Za jasného počasí dohlédnete od Javořice až po Devět skal. Důstojná tečka za vyhlídkovým okruhem před návratem na základnu.', 49.5288, 15.8570, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Rosi%C4%8Dka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Rosi%C4%8Dka.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rozhledna Mařenka', 'Rozhledna na vrchu Mařenka u Štěměch stojí na nejvyšším bodě celého Třebíčska ve výšce 711 metrů. Z ochozu se otevírá kruhový výhled od Javořice přes Třebíč až k rakouským Alpám, které za ideálních podmínek vykreslí obzor. K věži vede krátká lesní procházka od parkoviště.', 49.1919, 15.7391, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Ma%C5%99enka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Ma%C5%99enka.jpg"}'::text[], 0),
    (v_route, 'Větrný mlýn v Třebíči', 'Zděný větrný mlýn holandského typu na kopci nad třebíčskou čtvrtí Zámostí je poslední svého druhu ve městě — kdysi nemlel mouku, ale tříslo pro koželuhy. Od mlýna je pěkný výhled na střechy Třebíče. Rychlá a fotogenická zastávka stranou turistického ruchu.', 49.2202, 15.8688, 'https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D%2C_v%C4%9Btrn%C3%BD_ml%C3%BDn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99eb%C3%AD%C4%8D%2C_v%C4%9Btrn%C3%BD_ml%C3%BDn.jpg"}'::text[], 1),
    (v_route, 'Rozhledna Pekelný kopec', 'Moderní rozhledna jižně od Třebíče má půdorys šesticípé hvězdy a odkazuje tak na židovské památky města zapsané v UNESCO. Dřevěná konstrukce s ocelovým jádrem měří přes 26 metrů a nabízí výhled na Třebíč, Dukovany i Mařenku. Od parkoviště u silnice vede na vrchol pohodlná cesta lesem.', 49.1950, 15.8700, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Pekeln%C3%BD_kopec.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Pekeln%C3%BD_kopec.jpg"}'::text[], 2),
    (v_route, 'Zámek Valeč', 'Barokně upravený zámek ve Valči u Hrotovic prošel velkorysou obnovou a dnes funguje jako zámecký resort s restaurací a muzeem veteránů. Nádvoří a park jsou přístupné, sbírka historických aut potěší každého, kdo má rád stroje. Pohodlná zastávka na kávu v poslední třetině okruhu.', 49.1707, 16.0316, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vale%C4%8D%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vale%C4%8D%2C_z%C3%A1mek.jpg"}'::text[], 3),
    (v_route, 'Rozhledna Babylon', 'Klasicistní kamenná věž z roku 1831 u Kramolína je považována za nejstarší rozhlednu na Moravě — původně sloužila zeměměřičům při triangulaci monarchie. Z ochozu je výhled na Dalešickou přehradu, chladicí věže Dukovan i hluboké lesy nad Jihlavou. Důstojné zakončení vyhlídkového okruhu.', 49.1112, 16.1700, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Babylon.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna_Babylon.jpg"}'::text[], 4);
  insert into public.routes
