  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Památník Bible kralické', 'Muzeum v Kralicích nad Oslavou připomíná místo, kde bratrská tiskárna na konci 16. století vytiskla slavnou Bibli kralickou — základní kámen spisovné češtiny. Expozice ukazuje dobové tisky i archeologické nálezy z tvrze, kde se tajně tisklo. Krátká, ale silná kulturní zastávka na začátku okruhu.', 49.1985, 16.2015, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kralice_nad_Oslavou%2C_pam%C3%A1tn%C3%ADk_Bible_kralick%C3%A9.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kralice_nad_Oslavou%2C_pam%C3%A1tn%C3%ADk_Bible_kralick%C3%A9.jpg"}'::text[], 0),
    (v_route, 'Údolí Oslavy a Chvojnice', 'Rozlehlá přírodní rezervace chrání divoké, hluboko zaříznuté kaňony obou řek s prudkými skalnatými stráněmi, suťovými lesy a vzácnými druhy rostlin. Od Senorad se dá sejít k soutoku a projít se po hraně údolí s výhledy do zeleného moře korun. Jedno z posledních skutečně divokých říčních údolí na Moravě.', 49.1650, 16.2350, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Adol%C3%AD_Oslavy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Adol%C3%AD_Oslavy.jpg"}'::text[], 1),
    (v_route, 'Zřícenina Levnov (Ketkovický hrad)', 'Zřícenina zvaná také Ketkovický hrad korunuje strmý ostroh vysoko nad soutokem Oslavy a Chvojnice. Z hradu zbyly části paláce a hradeb, hlavním lákadlem je ale závratný výhled do kaňonu, který patří k nejhezčím na Vysočině. Od Ketkovic vede k hradu pohodová lesní stezka.', 49.1585, 16.2646, 'https://commons.wikimedia.org/wiki/Special:FilePath/Levnov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Levnov.jpg"}'::text[], 2),
    (v_route, 'Zřícenina Templštejn', 'Rozsáhlá zřícenina hradu templářů z konce 13. století se skrývá v lesích nad kaňonem Jihlavy u Jamolic. Dochované zdi z netradičně kladeného kamene a tajemná pověst řádu dodávají místu zvláštní atmosféru. Krátká procházka po červené značce od lesního parkoviště.', 49.0946, 16.2477, 'https://commons.wikimedia.org/wiki/Special:FilePath/Templ%C5%A1tejn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Templ%C5%A1tejn.jpg"}'::text[], 3),
    (v_route, 'Mohelenská hadcová step', 'Národní přírodní rezervace na hadcovém podloží nad obří smyčkou řeky Jihlavy je domovem stepní vegetace, kudlanek a desítek druhů, které jinde v Česku nenajdete. Z vyhlídky na hraně stepi se otevírá jeden z nejslavnějších pohledů Moravy — meandr řeky sevřený skalami sto metrů pod vámi. Nezapomenutelný vrchol celé trasy.', 49.1067, 16.1878, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mohelensk%C3%A1_hadcov%C3%A1_step.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mohelensk%C3%A1_hadcov%C3%A1_step.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Údolí Doubravy', 'Přírodní rezervace u Bílku chrání divoký kaňon říčky Doubravy s vodopádem, skalními útvary a vyhlídkou Čertův stolek. Okruh soutěskou Koryto patří k nejkrásnějším krátkým túrám na Vysočině — počítejte s hodinkou chůze. Motorku necháte na parkovišti u silnice v Bílku.', 49.6880, 15.6950, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Adol%C3%AD_Doubravy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%9Adol%C3%AD_Doubravy.jpg"}'::text[], 0),
    (v_route, 'Zámek Chotěboř', 'Barokní zámek rodu Dobrzenských s kaplí a parkem stojí na okraji města nad údolím Doubravy a hostí městské muzeum. Interiéry s rodovými sbírkami se prohlížejí s průvodcem, park je volně přístupný. Klidná kulturní zastávka po túře divokým údolím.', 49.7200, 15.6740, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chot%C4%9Bbo%C5%99%2C_z%C3%A1mek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chot%C4%9Bbo%C5%99%2C_z%C3%A1mek.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Panský dům (Chotěboř)', 'Tradiční hotel s restaurací přímo na chotěbořském náměstí vaří poctivou českou kuchyni a polední menu, na čepu bývá pivo z místního pivovaru Chotěboř. Hosté oceňují rychlou obsluhu a férové ceny. Praktická zastávka na oběd zhruba v třetině okruhu.', 49.7207, 15.6702, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chot%C4%9Bbo%C5%99%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chot%C4%9Bbo%C5%99%2C_n%C3%A1m%C4%9Bst%C3%AD.jpg"}'::text[], 2),
    (v_route, 'Vilémovický tis', 'Památný tis červený na návsi ve Vilémovicích patří k nejstarším stromům v Česku — odhady jeho věku sahají od patnácti set do dvou tisíc let. Mohutný strom s obvodem přes tři metry přežil generace a stále plodí. Kuriózní pětiminutová zastávka, kterou si nenechte ujít.', 49.7107, 15.3454, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vil%C3%A9movick%C3%BD_tis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vil%C3%A9movick%C3%BD_tis.jpg"}'::text[], 3),
    (v_route, 'Stvořidla', 'Legendární peřejnatý úsek Sázavy mezi Světlou a Ledčí, kde řeka hučí přes žulové balvany sevřená strmými lesnatými stráněmi. Přírodní rezervace je rájem vodáků při jarní vodě a Jaroslav Foglar sem zasadil tábor Hochů od Bobří řeky. Od parkoviště u trati vede k řece krátká stezka.', 49.6650, 15.3500, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stvo%C5%99idla.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stvo%C5%99idla.jpg"}'::text[], 4),
    (v_route, 'Melechov', 'Zalesněná hora nad Ledčí nad Sázavou bývá označována za pomyslný střed Evropy a její žulové vrcholové partie ukrývají skalní útvary i bývalou vojenskou pozorovatelnu. Silnice po úbočí nabízejí pěkné výhledy na kraj kolem Sázavy. Poslední zastávka před návratem do Mezné.', 49.6486, 15.3103, 'https://commons.wikimedia.org/wiki/Special:FilePath/Melechov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Melechov.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Jihlavské podzemí', 'Labyrint chodeb vytesaných ve skále pod historickým centrem Jihlavy měří přes dvacet kilometrů a je po Znojmu druhým největším podzemím v Česku. Prohlídka vede i tajemnou svítící chodbou, jejíž fosforeskující stěny dodnes vzbuzují otázky. V podzemí je stálých deset stupňů, vezměte si něco teplého.', 49.3961, 15.5906, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jihlavsk%C3%A9_podzem%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jihlavsk%C3%A9_podzem%C3%AD.jpg"}'::text[], 0),
    (v_route, 'Muzeum Vysočiny Jihlava', 'Hlavní muzeum kraje sídlí v renesančních domech přímo na Masarykově náměstí a vypráví příběh stříbrné horečky, která ve 13. století udělala z Jihlavy jedno z nejbohatších měst království. Expozice přibližují hornictví, přírodu i řemesla Vysočiny. Ideální start pro pochopení kraje, kterým celý den jezdíte.', 49.3956, 15.5907, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_Masarykovo_n%C3%A1m%C4%9Bst%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_Masarykovo_n%C3%A1m%C4%9Bst%C3%AD.jpg"}'::text[], 1),
    (v_route, 'Brána Matky Boží', 'Poslední dochovaná brána jihlavského městského opevnění s vyhlídkovým ochozem je symbolem města. Z věže vysoké přes dvacet metrů přehlédnete červené střechy historického jádra i okolní vrchovinu. Výstup spojte s procházkou po přilehlých hradbách a parkánech.', 49.3946, 15.5876, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_br%C3%A1na_Matky_Bo%C5%BE%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_br%C3%A1na_Matky_Bo%C5%BE%C3%AD.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Radniční restaurace (Jihlava)', 'Restaurace s vlastním minipivovarem v historických prostorách radničního domu na Masarykově náměstí patří k jihlavské klasice. Vaří poctivou českou kuchyni k čepovanému radničnímu pivu a hosté dlouhodobě chválí kuchyni i klenuté sály. Pohodlný oběd, než vyrazíte z Jihlavy na sever.', 49.3963, 15.5910, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_radnice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jihlava%2C_radnice.jpg"}'::text[], 3),
    (v_route, 'Šlakhamr', 'Středověký vodní hamr na řece Sázavě v Hamrech u Žďáru dodnes předvádí, jak obří kladiva poháněná vodním kolem kovala železo. Technické muzeum v Brně tu o víkendech pořádá ukázky kování, které stojí za načasování zastávky. Krásná技 památka v zeleném údolí přímo u silnice.', 49.5570, 15.8890, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0lakhamr.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0lakhamr.jpg"}'::text[], 4),
    (v_route, 'Havlíčkův dům (Havlíčkův Brod)', 'Renesanční dům na náměstí, kde žil novinář a buřič Karel Havlíček Borovský, dnes patří Muzeu Vysočiny a vypráví jeho příběh od Borové po vyhnanství v Brixenu. Expozice je moderní a vtipná, přesně v duchu Havlíčkových epigramů. Náměstí kolem nabízí kavárny na rychlé doplnění kofeinu.', 49.6079, 15.5806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Havl%C3%AD%C4%8Dk%C5%AFv_Brod%2C_Havl%C3%AD%C4%8Dk%C5%AFv_d%C5%AFm.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Havl%C3%AD%C4%8Dk%C5%AFv_Brod%2C_Havl%C3%AD%C4%8Dk%C5%AFv_d%C5%AFm.jpg"}'::text[], 5),
    (v_route, 'Michalův statek v Pohledi', 'Živý skanzen v malé vsi u Světlé nad Sázavou ukazuje selské hospodářství, jak vypadalo před staletími — roubenky, černou kuchyni, dobytek i políčka obdělávaná historickými postupy. Expozice Muzea Vysočiny přenese návštěvníka do života poddaného sedláka za časů roboty. Nečekaně silná tečka za muzejním okruhem.', 49.6550, 15.4570, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pohle%C4%8F%2C_Michal%C5%AFv_statek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pohle%C4%8F%2C_Michal%C5%AFv_statek.jpg"}'::text[], 6);
